INSERT INTO reviews(version_id,actor,decision,evidence,snapshot) SELECT v.id,'Aroha Chen','submitted','Synthetic demo committee pack', jsonb_build_object('programme',(SELECT to_jsonb(p) FROM programmes p WHERE p.id=v.programme_id),'version',to_jsonb(v),'modules',coalesce((SELECT jsonb_agg(x) FROM modules x WHERE x.version_id=v.id),'[]'::jsonb),'outcomes',coalesce((SELECT jsonb_agg(x) FROM outcomes x WHERE x.version_id=v.id),'[]'::jsonb),'assessments',coalesce((SELECT jsonb_agg(x) FROM assessments x WHERE x.version_id=v.id),'[]'::jsonb),'alignments',coalesce((SELECT jsonb_agg(x) FROM alignments x WHERE x.version_id=v.id),'[]'::jsonb),'assessment_outcomes',coalesce((SELECT jsonb_agg(x) FROM assessment_outcomes x WHERE x.version_id=v.id),'[]'::jsonb),'tasks',coalesce((SELECT jsonb_agg(x) FROM tasks x WHERE x.version_id=v.id),'[]'::jsonb)) FROM versions v WHERE id='00000000-0000-4000-8000-000000000301';
